(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ha"] = {"ui":{"skip":"Tsallake zuwa abubuwan shafin","back":"← Koma zuwa AI-gile","lang.button":"Harshe: {name}","lang.dialog":"Zaɓi harshe","lang.search":"Nemi harsuna","lang.none":"Babu harshen da ya dace","lang.notYet":"Ba a fassara {name} ba tukuna","theme.aria":"Canza yanayi: haske, duhu ko baƙi","theme.toLight":"Koma yanayin haske","theme.toDark":"Koma yanayin duhu","theme.toBlack":"Koma yanayin baƙi (baƙi na gaske, mai sauƙi ga allon OLED)","words.underline":"Ja layi a ƙarƙashin waɗannan kalmomi a shafin","words.underlineHelp":"Ku kai linzami kan kalma mai ɗigo ko ku taɓa ta don ganin ma'anarta.","index.title":"AI-gile: ƙungiyar AI ɗinku ta masu shirye-shirye, a allo ɗaya","index.description":"AI-gile allon kanban ne don ƙungiyoyin AI masu rubuta lamba. Suna aiki yayin da kuke barci; ku kuwa kuna samun ɗan tarin abubuwa don yanke shawara, gwadawa da karɓa.","hero.logoAlt":"Alamar allon AI-gile","hero.h1.html":"Ƙungiyar AI ɗinku ta masu shirye-shirye, a allo&nbsp;ɗaya.","hero.alpha":"🐣 Pre-alpha a rufe","hero.alphaTitle":"Na farko ne kuma ba a gama ba: na gode da gwadawa!","hero.lede":"Suna ginawa yayin da kuke barci. Kuna farkawa zuwa ɗan tarin kaɗan: 'yan tambayoyi, 'yan abubuwan gwadawa, lu'u-lu'u mai shuɗi ɗaya ko biyu. Danna, karɓa, ku koma kofi ɗinku.","dl.windows":"Manhajar Windows","dl.browser":"Gudanar da shi a browser","dl.messenger":"📱 Messenger don wayarku","dl.soon":"Nan ba da daɗewa ba","dl.notify":"🔔 Ku sanar da ni idan ya buɗe","dl.notifySmall":"Alpha ko beta","hero.secondary":"Agile, amma ƙungiyar ba ta taɓa buƙatar kofin tsaye na taro ba. (Duk da haka suna yin taron.)","pitch.h2":"AI-gile da kalmomi kamar yadda kuke so","pitch.lede":"Zaɓi tsayi, daga kalma ɗaya zuwa 144. Kowane tsayi bayaninsa ne na kansa, wanda aka rubuta don wannan girman. Ja maɓallin zamiya ko ku yi amfani da maɓallan kibiya.","pitch.rangeLabel":"Tsayi cikin kalmomi","pitch.dice":"🎲 wani sigar","pitch.words.one":"kalma {n}","pitch.words.other":"kalmomi {n}","pitch.letters.one":"harafi {n}","pitch.letters.other":"haruffa {n}","pitch.chars.one":"alama {n}","pitch.chars.other":"alamomi {n}","count.line.html.one":"kati {n} a allo yanzu","count.line.html.other":"kati {n} a allo yanzu","people.humans.html.one":"👥 mutum {n}","people.humans.html.other":"👥 mutane {n}","people.agents.html.one":"🤖 wakili {n}","people.agents.html.other":"🤖 wakilai {n}","people.working.html.one":"⚡ {n} na aiki yanzu","people.working.html.other":"⚡ {n} na aiki yanzu","pre.title":"AI-gile: ana gina wani abu","pre.description":"Ana gina wani abu a nan. Allo inda ƙungiyoyin AI ke gina abin da ka nema, kuma suna koya maka yayin da suke aiki. A yanzu pre-alpha ce a rufe tare da abokai.","pre.h1":"Ana gina wani abu a nan. 🤫","pre.line":"Allo inda ƙungiyoyin AI ke gina abin da ka nema, kuma suna koya maka yayin da suke aiki. A yanzu pre-alpha ce a rufe tare da abokai.","pre.btn":"🔔 Ku sanar da ni idan ya buɗe","pre.peek":"Bayan gilashi: ainihin allon, kai tsaye. Kowane kati layi ne mai launi.","pre.peekFake":"Bayan gilashi: haka allo yake idan ana aiki.","features.aria":"Abin da yake yi","f.pile.h":"Tari ɗaya a gare ku","f.pile.html":"<b>Gare ku</b> yana ɗauke da duk abin da ke jiran ku, a kowane aiki: tambayoyi, abubuwan gwadawa, ayyukan da mutum kaɗai zai iya yi. Layinku yana faɗin abin da ke gaba da tsawon lokacin da zai ɗauka.","f.sleep.h":"Ƙungiyoyi masu aiki yayin da kuke barci","f.sleep.p":"Kowane aiki yana da jagora da ƙungiyar wakilan AI. Ku yi sharhi a kan kati sai ƙungiyar ta farka, ta yi aikin, ta mayar da shi da matakan da gajiyayyen mutum zai iya bi.","f.tester.h":"Mai gwajin AI yana dubawa tukuna","f.tester.p":"Kafin wani abu ya zo gare ku, mai gwaji yana bin matakai a kwafin manhajar kuma yana nuna abin da ya gani, da hoton allo. Ku duba waɗanda suka yi nasara ku karɓa da danna ɗaya.","f.proof.h":"Shaida, ba alkawari ba","f.proof.p":"Kowace miƙawa tana nuna abin da ya canza: fayilolin, bambancin, hotunan allo. Ba sai kun buɗe kowace manhaja don ganin an gama ba.","f.chat.h":"Ku yi hira da jagororinku","f.chat.p":"Ginshiƙi irin na Discord: alama ɗaya ga kowane aiki, lu'u-lu'u masu shuɗi ga abin da ke buƙatar ku. Ku aika wa jagora ra'ayi; zai mayar da shi kati da shiri, tare da maɓallin ✅ Go.","f.tidy.h":"Yana tsara kansa","f.tidy.p":"Katuna masu alaƙa suna haɗuwa wuri ɗaya, ana gyara taken da suka ruɗe, kuma duba token yana sa lamba ta zama marar nauyi. Ƙarancin abubuwan da za a sauya tsakaninsu, ƙarancin tunani.","f.private.h":"Naku ne, a kwamfutarku","f.private.li1":"Allon yana aiki a injin ɗinku kuma yana amsa muku kaɗai.","f.private.li2":"DM na sirri tsakanin mutane an ɓoye su daga ƙarshe zuwa ƙarshe.","f.private.li3":"Babu asusu, babu masu bin diddigi, babu kuki.","f.lang.h":"A cikin harshenku","f.lang.p":"Harsuna sama da 120, daga Dutch, Welsh da Japananci zuwa na 'yan fashin teku, Yoda da Klingon, da saurin komawa Turanci don kalmomin sana'a.","f.service.h":"Daga ra'ayi zuwa sabis na gaske","f.service.p":"Ka gina wani abu da AI da mutane ke amfani da shi yanzu? Yi masa alama a matsayin sabis kuma allon zai taimaka maka ka gudanar da shi da kyau: binciken uptime, shafin matsayi na jama'a, matsaloli da rubutaccen bita, canje-canje da ke buƙatar Go, ajiyar tsaro da ake dubawa kowace rana. Taimako yana koya maka kowane mataki yayin da kake tafiya.","msgr.h2":"AI-gile Messenger: ƙungiyarku a aljihunku","msgr.p1":"Ku yi magana da ƙungiyarku ta AI ba tare da buɗe allo ba. Ku yi hira da jagororin ayyukanku da abokanku, ku ga matakan gwajin kati ku amsa su, duka daga wayarku.","msgr.p2":"Don haɗa ta, ku duba lambar QR a kan allonku. Karon farko? Hirar demo mai daɗi za ta nuna muku yadda komai yake.","msgr.when":"Android da farko, sannan sigar yanar gizo don wayoyi da iPhone.","msgr.who":"Jagoran aikinku","msgr.b1":"Gyaran yanayin duhu ya shirya. Kuna son matakan gwajin?","msgr.b2":"Eh, don Allah!","msgr.b3":"1. Buɗe Saiti. 2. Zaɓi Duhu. Yana da kyau kuwa?","tl.aria":"Jerin lokaci daga tattaunawar farko zuwa taswirar gaba","tl.h2":"Daga tattaunawar farko zuwa abin da ke gaba","tl.lede":"Kwanaki da lokuta na gaske, a yankin lokacinku. Bayan yau shiri ne, ba tare da alƙawarin kwanan wata ba.","tl.today":"Yau","tl.planned":"a shirye","tl.cards.one":"kati {n}","tl.cards.other":"katuna {n}","join.h2":"Ku shiga","join.lede":"Wani mutum mai gemu, ɗan baƙon hali, mai AuDHD da wasu gwagwarmaya da lafiyar ƙwaƙwalwa, tare da wakilai masu haƙuri da yawa ne ke gina AI-gile. Na sirri ne a yanzu, a alpha a rufe tare da abokai. Kuna son gwadawa idan ya buɗe?","join.btn":"Yi rijistar sha'awa","join.small":"Za mu rubuto muku imel, ba wani abu ba","footer.tag":"AI-gile. Babu masu bin diddigi, babu kuki, babu kofin tsaye na taro.","footer.licence":"Lasisin kasuwanci","footer.status":"Matsayi","footer.privacy":"Abin da muke ajiyewa","footer.thanks":"Kira albarkacin ChilledChat","form.sending":"Ana aikawa…","form.failed":"Hakan bai yi aiki ba: ku sake gwadawa daga baya.","form.offline":"Ba a iya isa ga AI-gile ba: ku sake gwadawa daga baya.","form.keep":"Muna amfani da wannan ne kawai don mu ba ku amsa, sannan mu goge shi. Babu masu bin diddigi, babu kuki.","form.keepLink":"Abin da muke ajiyewa","interest.title":"AI-gile: ku sanar da ni idan alpha ya buɗe","interest.description":"Ku bar imel ɗinku don jin lokacin da alpha ko beta na AI-gile a rufe zai buɗe.","interest.h1":"🔔 Ku sanar da ni idan ya buɗe","interest.lede":"AI-gile yana pre-alpha a rufe. Ku bar imel ɗinku za mu rubuto sau ɗaya, idan akwai wuri a gare ku.","interest.email":"Imel ɗinku","interest.which":"Wane gwaji?","interest.alpha":"Alpha a rufe: da wuri, mai tsauri, sauye-sauye da yawa","interest.beta":"Beta: ya fi tsayawa, daga baya","interest.both":"Duk ɗaya, wanda ya fara zuwa","interest.submit":"Saka ni cikin jerin","interest.thanks":"Na gode! Kuna cikin jerin.","licence.title":"AI-gile: lasisin kasuwanci","licence.description":"Kuna amfani da AI-gile a kasuwancinku? Ku nemi lasisin kasuwanci kyauta.","licence.h1":"📜 Lasisin kasuwanci","licence.lede":"Kuna amfani da AI-gile a wurin aiki? Ku gaya mana ko ku wane ne da abin da kuke yi. Idan yana yin alheri, lasisin kyauta ne.","licence.company":"Kamfani","licence.website":"Shafin yanar gizo","licence.what":"Abin da kuke yi","licence.how":"Yadda yake taimakon duniya","licence.email":"Imel","licence.submit":"Nema","licence.thanks":"Na gode! Za mu amsa ta imel.","status.title":"Matsayin AI-gile","status.h1":"Matsayin AI-gile","status.quiet":"Komai lafiya","status.intro":"Shin AI-gile yana aiki yanzu? Wannan shafi yana duba gidan yanar gizo, raba allo, kira da saukarwa duk bayan minti 5.","status.up":"Yana aiki (ya amsa cikin {ms} ms)","status.slow":"Bai amsa dubawar ƙarshe ba, ana sake gwadawa","status.down":"Ya faɗi: bai amsa dubawa biyu na ƙarshe ba","status.svc.web":"Gidan yanar gizo","status.svc.web.offers":"Wannan shafin: menene AI-gile, da fom ɗin sha'awa","status.svc.boards":"Raba allo","status.svc.boards.offers":"Alluna na jama'a, saƙonni tsakanin abokai da gayyata","status.svc.calls":"Kira","status.svc.calls.offers":"Murya, bidiyo da raba fuskar na'ura a AI-gile","status.svc.download":"Saukarwa","status.svc.download.offers":"Mai shigarwa na Windows da hanyoyin gayyata","status.checking":"Ana dubawa…","status.offline":"Ba a iya isa ga sabis ɗin matsayi yanzu (ana sake gwadawa)","status.updated":"an sabunta {ago}","status.justNow":"yanzu-yanzu","status.min":"mintuna {n} da suka wuce","status.hours":"awa {n} da ta wuce","status.days":"kwana {n} da suka wuce","privacy.title":"AI-gile: abin da muke ajiyewa","privacy.h1":"Abin da muke ajiyewa","privacy.lede":"A taƙaice: abin da kuka aiko mana kawai, kuma ba na dogon lokaci ba.","privacy.only":"Abin da kuka aiko mana kawai: abin da kuka rubuta a fom, kamar imel ɗinku. Babu wani abu kuma game da ku.","privacy.sealed":"Ana rufe shi da hatimi don kada sabarmu ta iya karanta shi: a cikin browser ɗinku kafin ya tafi (a tsohon browser, a lokacin da ya iso). Allonmu kaɗai ne zai iya buɗe shi.","privacy.server":"Ana goge shi daga sabar da zarar ya isa allonmu. Duk abin da ya rage a can bayan kwana 30 ana goge shi ko ta yaya.","privacy.board":"Muna ajiye shi a allonmu ne kawai har sai mun ba ku amsa, sannan mu goge shi a can ma.","privacy.none":"Babu masu bin diddigi, babu kuki, babu nazarin bayanai.","privacy.local":"Harshenku da zaɓinku na haske ko duhu suna zama a cikin browser ɗinku. Ba a taɓa aiko mana da su ba.","privacy.ask":"Kuna so a goge shi da wuri? Ku amsa imel ɗinmu ku faɗa mana.","live.h2":"Kalli yadda ake gina shi, kai tsaye","live.caption":"An ɓoye kowane kati: kana ganin siffar aikin, ba kalmomin ba.","live.watching.one":"kai tsaye: {n} na kallo","live.watching.other":"kai tsaye: {n} na kallo","live.last.now":"An motsa katin ƙarshe yanzu-yanzu","live.last.min.one":"An motsa katin ƙarshe mintuna {n} da suka wuce","live.last.min.other":"An motsa katin ƙarshe mintuna {n} da suka wuce","live.last.hour.one":"An motsa katin ƙarshe awa {n} da ta wuce","live.last.hour.other":"An motsa katin ƙarshe awanni {n} da suka wuce","live.last.day.one":"An motsa katin ƙarshe rana {n} da ta wuce","live.last.day.other":"An motsa katin ƙarshe kwanaki {n} da suka wuce","live.offline":"Allon kai tsaye yana hutawa kaɗan. Ka sake dubawa nan ba da jimawa ba.","live.cols":"Backlog|A yi|Ana yi|Ƙungiya na dubawa|Don a gwada|Don ƙungiya|An gama"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Mutummutumai.","Wakilta."]},{"n":2,"texts":["Mutummutumi kanban.","Wakilai tsararru.","Ra'ayoyi, gini."]},{"n":3,"texts":["Kanban don mutummutumai.","Ra'ayoyi su zama fasali.","Kanban na wakilai, kyauta."]},{"n":5,"texts":["Allon kanban da wakilai ke tafiyarwa.","Ku rubuta kati. Wakilai su gina.","Kyauta, na gida, ɗan wasa."]},{"n":8,"texts":["Allon kanban kyauta inda wakilan AI ke aiki.","Rubuta ra'ayi. Wakilai su gina shi. Ku karɓa.","Agile don mutum ɗaya da mutummutumai masu haƙuri da yawa."]},{"n":13,"texts":["Allon kanban a kwamfutarku inda wakilan AI ke ɗaukar katunan aiki.","Rubuta ra'ayi. Ƙungiyar wakilai ta gina shi. Mai gwaji ya duba.","Kyauta, babu asusu ko masu bin diddigi: allo, wasu mutummutumai, kuma ku ne shugaba."]},{"n":21,"texts":["AI-gile allon kanban ne don aiki da wakilan AI masu rubuta lamba. Su ke ɗaukar katunan; ku kuwa kuna gwadawa da karɓa.","Kowane aiki yana samun jagora da ƙungiyar wakilan AI. Ku yi sharhi a kowane kati sai ƙungiyar ta fara aiki.","Allon ayyuka na kai, kyauta, mai aiki a kwamfutarku. Ma'aikata mutummutumai ne. Wanda ke cewa eh, ku ne."]},{"n":34,"texts":["Kuna sa ra'ayoyi a allo. Ƙungiyar wakilan AI tana mayar da su fasalolin da ke aiki, tana gwada su, ta mayar muku da su tare da matakan gwadawa. Babu abin da ake ƙirgawa an gama sai kun faɗa.","AI-gile allon kanban ne na gida da Rich ya gina da taimako mai yawa daga wakilan da yake gudanarwa yanzu. Kyauta ne, yana aiki a kwamfutarku, ana raba shi da abokai, ba a sayarwa ba.","Ku yi tunanin allon kanban na yau da kullum, da ginshiƙai daga Backlog zuwa An gama, amma wakilan AI ne ke ɗaukar katunan. Suna ba da rahoton ci gaba, suna tambaya idan sun makale, kuma kullum suna jiran yardarku."]},{"n":55,"texts":["AI-gile allon kanban ne inda ƙungiyar ta kunshi wakilan AI. Kowane aiki yana da jagora da ke tsara aikin da masu taimako da ke gina shi. Idan fasali ya shirya, mai gwajin AI yana gwada shi ya ɗauki hoton allo, sannan ya isa tarinku. Ku karɓa, ko ku yi sharhi su sake yi.","Ya fara ne a matsayin hanyar mutum ɗaya na bin zaman rubuta lamba na AI da yawa lokaci guda, sannan ya girma ya zama allo na gaske. Yana aiki a injin ɗinku, ba ya buƙatar asusu, kuma ba shi da masu bin diddigi. Haka kuma ba a gama ba, don haka ku sa ran gefuna masu tsauri da wani abin mamaki.","Ga sigar gaskiya. Har yanzu dole ne ku kasance da ra'ayoyin, kuma dole ne ku duba sakamakon. Abin da AI-gile ke yi shi ne duk abin da ke tsakanin: yana tsara katunan, yana tashe wakilin da ya dace idan kun yi sharhi, yana nuna daidai abin da ya canza, kuma yana tara komai a ɗan gajeren tari a gare ku."]},{"n":89,"texts":["AI-gile allon kanban ne kyauta da kuke gudanarwa a kwamfutarku. Maimakon mutane, kowane aiki yana da ƙungiyar wakilan AI: jagora da ke mayar da ra'ayoyinku kati da shiri, da masu taimako da ke ɗaukar katunan bisa fifiko. Idan an gina wani abu, mai gwajin AI yana bin matakan gwaji ya nuna muku abin da ya gani. Sannan yana jira a tari ɗaya mai suna Gare ku. Kuna karɓa, ko ku yi sharhi ƙungiyar ta sake gwadawa. Babu abin da ke isa An gama ba tare da ku ba.","Akwai wasu siffofi da ba za ku yi tsammani ba. Tsaron dare yana cika ginshiƙin A yi yayin da kuke barci, yana zaɓar katunan da ba sa buƙatar amsarku. Na'urar ƙidayar token tana nuna yawan da wakilai suka yi amfani da shi yau da wannan mako, kuma Yanayin Babu Token yana gaya musu su daina kashewa. Kuna iya aika saƙo ga abokai, kuma saƙonnin sirri an ɓoye su daga ƙarshe zuwa ƙarshe. Allon yana magana da harsuna kusan 120, ciki har da Dutch, Flemish, na 'yan fashin teku da Klingon. Babu ɗaya daga cikinsu da ke da farashi, kuma babu wanda ke ƙoƙarin sayar muku.","AI-gile ƙaramin aiki ne na kai, ba kamfani ba. Rich yana son kula da ayyukan rubuta lamba na AI da yawa ba tare da buɗe kowace manhaja ya duba ba, don haka shi da wakilai suka gina allo don haka, sannan suka yi amfani da allon wajen gina sauran. Yana pre-alpha a rufe, ma'ana yana aiki, galibi, ga ɗimbin abokai. Babu shafin farashi, babu jaridar imel, babu shirin girma. Idan ya yi kama da mai amfani, kuna iya neman gwadawa idan ya buɗe kaɗan."]},{"n":144,"texts":["AI-gile allon kanban ne don mutum ɗaya da wakilan AI da yawa. Yana aiki a kwamfutarku kuma kyauta ne gaba ɗaya. Kuna ƙara ayyuka, kuma kowane aiki yana samun jagora da ƙaramar ƙungiya. Kuna hira da jagora, kamar Discord, kuna kwatanta ra'ayi; jagora yana mayar da shi kati da shiri, sannan yana jiran ku danna Go. Ƙungiyar tana aiki ta cikin katunan bisa fifiko, da layin umarni mai sauƙi da aka yi wa samfuran harshe. Kafin wani abu ya dawo gare ku, mai gwajin AI yana bin matakai a kwafin manhajar ya haɗa hoton allo. Aikin da aka gama yana isa tarinku tare da fayilolin da suka canza da bambancin. Kuna karɓa, ko ku bar sharhi ƙungiyar ta farka ta sake gwadawa. Ku kaɗai ne za ku iya matsar da kati zuwa An gama.","Kwana ɗaya da AI-gile, kusan. Da yamma kuna barin sharhi kaɗan: wannan maɓalli yana wurin da bai dace ba, ya kamata a jera wancan jerin, za mu iya samun yanayin duhu. Kuna kwanciya barci. Wakilai suna karanta sharhin, suna yin sauye-sauyen, suna gwada su, suna mayar muku. Idan A yi ya ƙare, tsaron dare yana cika shi daga backlog da katunan da ba sa buƙatar amsarku. Da safe akwai tari ɗaya gajere: tambayoyi biyu da abubuwan gwadawa kaɗan, kowanne da matakan da mai barci zai iya bi da hoton allo na yana aiki. Kuna danna, kuna karɓar masu kyau, kuna mayar da sauran. Na'urar ƙidayar token tana nuna abin da aka yi amfani da shi, kuma Yanayin Babu Token yana nan don makonni masu sauƙi. Sannan kuna karin kumallo, wanda wakilai ba za su iya taimako a kai ba tukuna.","Da farko, abin da AI-gile ba shi ba. Ba kamfanin farawa ba ne, ba na sayarwa ba, kuma babu wanda ke tattara bayananku. Allo ne kyauta da ke aiki a kwamfutarku, babu asusu, babu masu bin diddigi, babu kuki. Abin da yake shi ne: wuri ɗaya mai tsabta don ganin duk ayyukan rubuta lamba na AI a lokaci guda, da ƙungiyar wakilai suna yin katunan, ku kuma kuna yanke shawara. Yana haɗa katunan masu alaƙa, yana gyara taken da suka ruɗe, kuma yana lura da yadda lamba take zama marar nauyi. Yana magana da harsuna kusan 120, daga Dutch da Flemish zuwa na 'yan fashin teku da Klingon. Abokai za su iya aika wa juna saƙo, a sirri kuma a ɓoye. Rich da wakilai masu haƙuri da yawa ne suka gina shi, galibi suna amfani da shi da kansa. Yana pre-alpha a rufe, don haka akwai tsauri a wurare. Idan ya yi kama da nishaɗi, ku nemi da ladabi kuma wataƙila ku shiga da wuri."]}],"quips":{"1":"Kalma ɗaya. Jarumtaka. Wataƙila ta wuce kima.","3":"Kalmomi uku. Sun fi gaskiya fiye da yawancin shafukan samfura.","8":"Kalmomi takwas. Har yanzu sun fi taro gajarta.","21":"Tsawon kalmomi maki na labari ne, ta hanya. Ai haka ne.","55":"Kalmomi hamsin da biyar. An gama katuna biyu yayin da kuke karanta wannan.","144":"Wannan shi ne dogon. Babu 233. Wakilai sun tafi barci."}},"timeline":{"first-idea.name":"Ra'ayin farko","first-idea.line":"Tattaunawa ta farko, kafin wata lamba ta wanzu.","first-board.name":"Allo na farko","first-board.line":"Allon da ke bin diddigin ginin kansa: katuna, ginshiƙai, ja da sauke, ayyuka.","team-roles.name":"Ƙungiya da matsayi","team-roles.line":"Bayanan wakilai, samfuran ƙungiya, wurare da wanda ke yin me.","install.name":"Shigarwa da fitarwa","install.line":"Zip da aboki zai iya shigarwa, sabuntawa kai-tsaye, hanyoyi da komawa baya.","usage-saver.name":"Tanadin amfani","usage-saver.line":"Auna abin da gudanarwa ke ci, kiyaye lamba marar nauyi, ajiye iyakarku.","friends.name":"Abokai da rabawa","friends.line":"DM na sirri, na'urar isar da saƙo a ɓoye, gayyata, matsayi da ayyukan da aka raba.","languages.name":"Harsuna","languages.line":"Kowane rubutun allo a cikin fayil na harshe, Dutch da Flemish na farko.","ai-tester.name":"Mai gwajin AI","ai-tester.line":"Mai gwaji yana duba kowace miƙawa tukuna kuma yana nuna abin da ya gani.","website.name":"Shafin yanar gizo","website.line":"aigile.lol, gwaji na farko da wannan jerin lokaci.","streaming.name":"Hira da yawo","streaming.line":"Discord, Twitch, OBS, yanayin mai yawo, GIF da emoji.","no-ai.name":"Fitowar babu AI","no-ai.line":"Allo ga masu rubuta lamba babu AI, da allunan jama'a.","night-watch.name":"Tsaron dare","night-watch.line":"Mai tsaro da Scrum Master suna kiyaye ƙungiyoyi a kan aiki yayin da kuke barci.","p-more.name":"Duk sauran","p-more.line":"Ƙananan ra'ayoyi da ke jiran lokacinsu.","p-android.name":"Waya da Android","p-android.line":"Isa allonku daga waya, sannan manhajar Android ta asali.","p-release.name":"Alpha da bayansa","p-release.line":"Alpha a rufe, shafin kai-tsaye, sannan beta.","p-languages.name":"Ƙarin harsuna","p-languages.line":"Fiye da harsuna ɗari, da yanayin nutsewa ga masu koyo.","p-engines.name":"Ƙarin injunan AI","p-engines.line":"Zaɓi Claude, Codex ko Gemini ga kowane wakili.","p-pro.name":"Aikin ƙwararru","p-pro.line":"Alamomin haɗari, ƙofofin haɗawa, katunan faruwa da shingaye.","p-self.name":"Kula da ku","p-self.line":"Yanayin gajiya, tunatarwar kula da kai da 4:20.","p-servers.name":"Sabobi da girma","p-servers.line":"Saitunan sabar na duniya, matsayi da tsara girma.","p-livestream.name":"Ƙarin yawo","p-livestream.line":"Hirar Twitch, emoji na kai da kallon kai-tsaye na jama'a."},"words":{"button":"📖 Kalmomin sana'a","h":"📖 Bayanin kalmomi","intro":"Kalmomin da za ka gamu da su a AI-gile, da Hausa mai sauƙi: gina shi, canza shi lafiya, ci gaba da sa shi aiki ga mutanen da ke amfani da shi, da aiki tare a matsayin ƙungiya da AI.","search":"Nemo kalma…","none":"Babu kalmar da ta dace da wannan.","close":"Rufe","count":{"one":"kalma {count}","other":"kalmomi {count}"},"groups":[{"id":"build","name":"🛠️ Gina shi"},{"id":"change","name":"🔀 Canza shi lafiya"},{"id":"run","name":"🛎️ Gudanar da sabis"},{"id":"team","name":"🤝 Aiki a matsayin ƙungiya (da kuma tare da AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Babban fayil ɗin lamba na aiki da cikakken tarihin commits, yawanci kuma ana adana shi a GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Layin aiki na daban a cikin lamba, don a yi canje-canje ba tare da taɓa babbar sigar ba.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Hoton lamba da aka adana, tare da gajeren bayanin abin da ya canja. Kullum za a iya komawa ɗaya.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Aika hotunan da aka adana (commits) daga wannan kwamfuta zuwa GitHub, don a adana su a raba su."},{"id":"merge","g":"build","word":"Merge","text":"Mayar da canje-canjen branch cikin babbar sigar."},{"id":"pr","g":"build","word":"Pull request","text":"Neman a duba canje-canjen branch a haɗa su cikin babbar sigar.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tsara lamba ba tare da canja abin da take yi ba: ƙananan fayiloli, sunaye masu haske, ƙarancin maimaitawa."},{"id":"bug","g":"build","word":"Bug","text":"Wani abu da ba ya aiki yadda ya kamata.","also":["bugs"]},{"id":"test","g":"build","word":"Gwaji","text":"Gwada aikin da aka gama don tabbatar yana yin abin da aka nema, kafin a karɓa.","also":["gwada","gwadawa","gwaje-gwaje","gwajin","test","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Gajeriyar quality assurance (tabbatar da inganci): binciken atomatik da ke gudana kafin wani abu ya fita kai tsaye. Idan QA ja ne, wani abu ya gaza, kuma ba zai fita kai tsaye ba sai an gyara shi.","also":["binciken inganci","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Sa sabuwar sigar ta fara aiki, misali a sabar da mutane ke amfani da ita."},{"id":"release","g":"change","word":"Sakewa","text":"Tarin aikin da aka gama mai suna wanda ke fita kai tsaye tare, da gajerun bayanai kan abin da ya canza. 🚀 Sakewa na rubuta bayanan daga katunan da aka gama.","also":["sakewa","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Komawa sigar ƙarshe da ke aiki idan sabuwa ta kawo matsala. A AI-gile yana yin jerin matakan mayarwa da aka rubuta a kan kowane canji.","also":["roll back","mayar da baya"]},{"id":"live","g":"change","word":"Kai tsaye","text":"Ainihin sigar da mutane ke amfani da ita, ba kwafi don gwada abubuwa ba. Masu haɓakawa kuma suna kiranta production.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"Canji","text":"Canjin da aka tsara a kan abin da mutane suka dogara da shi, an rubuta shi tukuna: me, me yasa, haɗarin, yaushe, da yadda za a mayar da shi. Fara ɗaya da 🔀 Gabatar da canji.","also":["canje-canje","buƙatar canji","change request"],"noTip":1},{"id":"risk","g":"change","word":"Haɗari","text":"Wani abu da zai iya lalacewa, an ba shi maki gwargwadon yiwuwarsa da girman illarsa. ⚠️ Haɗura na ajiye su a jeri ɗaya, mafi girman maki a farko, kowanne da ranar sake dubawa.","also":["haɗura","rajistar haɗura","risk register"]},{"id":"chgwin","g":"change","word":"Tagar canji","text":"Lokutan da canje-canje za su iya fita kai tsaye, kamar maraicen Talata mai shiru. A wajen taga ba za a iya gama katin canji ba, sai dai idan gaggawa ce.","also":["tagogin canji","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Ƙuri'a cikin sauri kafin canji ya fita kai tsaye: kowane mutum da dole ne ya amince yana cewa Go ko No go. Yana ci gaba ne kawai idan sun yarda.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Amincewa","text":"Jiran “eh” kafin aiki ya fara. Katin da aboki ya gabatar, ko canji, yana jira a ✅ Amincewa har sai ka amince ko ka ƙi.","also":["approval","approvals"]},{"id":"quiettime","g":"change","word":"Lokacin shiru","text":"Wani lokaci, kamar watsa shirye-shirye, nuni ko dare, da babu abin da ke fita kai tsaye. Ƙungiyoyi suna ci gaba da aiki da gwaji, amma fita kai tsaye na jira har ya ƙare. A wasu wurare ana kiransa change freeze.","also":["lokutan shiru","change freeze"]},{"id":"service","g":"run","word":"Sabis","text":"Abin da ka gina da mutane suka dogara da shi, kamar shafin yanar gizo ko manhaja, ana kula da shi don ya ci gaba da aiki. Yi alama a “Wannan aiki sabis ne” ka faɗi abin da yake bayarwa, wa ke amfani da shi da wa ke kan kira.","also":["sabis-sabis","service"]},{"id":"uptime","g":"run","word":"Binciken uptime","text":"Bincike na atomatik, bayan 'yan mintuna, cewa sabis ɗinka yana amsawa har yanzu. Idan ya gaza sau da yawa a jere, AI-gile zai buɗe katin matsala da kansa.","also":["uptime","binciken aiki"]},{"id":"statuspage","g":"run","word":"Shafin matsayi","text":"Shafin jama'a da ke nuna ko sabis yana aiki (kore, lemu ko ja) tare da sabon bayani, don mutanen da ke amfani da shi su duba maimakon tambaya.","also":["shafukan matsayi","status page"]},{"id":"incident","g":"run","word":"Matsala","text":"Wani abu da ya lalace ga mutanen da ke amfani da shi a yanzu, kamar shafin yanar gizo ya faɗi. Katin 🔥 matsala yana tsallake layi: sake sa shi aiki shi ne na farko.","also":["matsaloli","incident"]},{"id":"major","g":"run","word":"Babbar matsala","text":"Matsala mai girma sosai: mutane da yawa abin ya shafa, ko kuɗi ko bayanai suna cikin haɗari. Maɓalli ɗaya yana sa dukkan ƙungiyoyi a kanta (swarm), yana tashe duk wanda ke kan kira, kuma yana neman bayanin matsayi kowane mintuna 30.","also":["manyan matsaloli","major incident"]},{"id":"oncall","g":"run","word":"Kan kira","text":"Kasancewa wanda ke amsawa idan wani abu ya lalace, ko da da dare. Kowane sabis yana da memba na ƙungiya a kan kira wanda ake tashe da farko don matsalolinsa.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Lokacin amsa","text":"Tsawon lokacin da kati zai iya jira amsa ta farko, misali awa ɗaya don matsala. Bayan haka yana samun agogo ja, don kada a manta da wani abu shiru. Ana kuma kiransa burin amsa.","also":["lokutan amsa","burin amsa","response target"]},{"id":"postmortem","g":"run","word":"Bita bayan matsala","text":"Ɗan duba baya bayan matsala: abin da ya faru, abin da ya taimaka da abin da za a canza, ba tare da zargin kowa ba. Ba za a iya rufe matsala ba sai da ita.","also":["post-mortem","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Matsala mai maimaituwa","text":"Ɓoyayyen dalili a bayan matsala ɗaya ko fiye. Katin 🧩 matsala mai maimaituwa yana tara matsalolin da ke ta dawowa, don a gano dalilin a gyara shi har abada.","also":["problem","matsalar tushe"],"noTip":1},{"id":"rootcause","g":"run","word":"Tushen dalili","text":"Ainihin dalilin da ya sa wani abu ya lalace, ba kawai abin da ka ga ya ɓaci ba. Gyara tushen dalilin, matsalar za ta daina dawowa.","also":["tushen matsala","root cause"]},{"id":"workaround","g":"run","word":"Mafita na ɗan lokaci","text":"Hanyar sa abubuwa su ci gaba da aiki har ainihin gyaran ya shirya, kamar sake kunna wani abu idan ya makale. Ana rubuta ta a katin matsala mai maimaituwa don kada wani ya sake nemo ta.","also":["hanyar wucin gadi","workaround"]},{"id":"knownerror","g":"run","word":"Kuskuren da aka sani","text":"Matsala mai maimaituwa da aka fahimci dalilinta kuma tana da mafita na ɗan lokaci, amma ba a gyara ta ba tukuna. 🧩 Kurakuran da aka sani na jera su, don kowa ya yi amfani da mafitar maimakon sake tona.","also":["kurakuran da aka sani","known error"]},{"id":"runbook","g":"run","word":"Littafin aiki","text":"Umarnin mataki-mataki don gyara wani irin matsalar da aka sani, don a yi ta hanya ɗaya, cikin sauri, kowane lokaci. Bayan babbar matsala ƙungiyar za ta iya ba da shawarar ɗaya don ka ba da OK.","also":["runbook","runbooks"]},{"id":"backup","g":"run","word":"Ajiyar tsaro","text":"Kwafin bayananka da aka ajiye tun da, don a koma gare shi idan wani abu ya ɓace ko ya lalace. AI-gile na yin ajiyar tsaro na allunanka kowace rana.","also":["backup","backups"]},{"id":"restore","g":"run","word":"Maido","text":"Mayar da bayanai daga ajiyar tsaro. Ajiyar tsaro tana da amfani da gaske ne kawai idan ka san za a iya maido ta, don haka yana da kyau a gwada lokaci-lokaci.","also":["maidowa","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ra'ayoyi da aikin da ba a tsara su ba tukuna. Ba a yin aiki a kan komai a can sai ya koma A yi."},{"id":"sprint","g":"team","word":"Sprint","text":"Gajeren lokaci na aiki (sau da yawa mako ɗaya ko biyu) da aka amince da adadin katunan da za a gama.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Takaitaccen taro: abin da kowane memba ya yi, abin da zai yi na gaba, da abin da ke hana shi.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Allo mai ginshiƙai (A yi, Ana yi, An gama) inda katuna ke tafiya daga hagu zuwa dama yayin da ake aiki."},{"id":"wip","g":"team","word":"Iyakar WIP","text":"Aiki a ci gaba: mafi yawan katunan da ginshiƙi zai ɗauka, don ƙungiya ta gama abubuwa kafin ta fara wasu.","also":["WIP"]},{"id":"dod","g":"team","word":"Ma'anar An gama","text":"Gajeren jerin ƙungiyar na abin da “an gama” ke nufi, kamar an gwada kuma an bayyana, kafin a miƙa maka kati. Tagwayenta, Ma'anar Shirye, tana faɗin lokacin da kati ya isa a fara shi.","also":["Definition of Done","Ma'anar Shirye","Definition of Ready"]},{"id":"testpile","g":"team","word":"Tarin gwaji","text":"Katunan da aka gama da ke jiran ka gwada, ɗaya bayan ɗaya. Karɓi ɗaya ko mayar da shi da bayani, sai na gaba ya bayyana.","also":["test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Waiwaye kan yadda ƙungiyar ke aiki, don a amince da abu ɗaya da za a inganta. A AI-gile retro yana ba da shawarar canji a hanyoyin aikin ƙungiyar, kai kuma ka ce Go ko Ba tukuna ba.","also":["retros","retrospective","waiwaye"]},{"id":"peerreview","g":"team","word":"Bitar abokin aiki","text":"Idanu na biyu: wani AI yana duba aikin kowane kati kafin ya iso gare ka, don kurakurai kaɗan ne kawai su wuce.","also":["peer review","code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Kowa ya taru: kowace ƙungiya tana barin sauran aiki don taimakawa a kan aiki ɗaya na gaggawa har sai an warware shi. Sauran ayyuka suna jira a halin yanzu.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Wanda ke sa aiki ya ci gaba da gudana: yana lura da katunan da suka makale, yana tunatar da ƙungiyoyi, kuma yana tuna maka abin da ke jira. A AI-gile Lead Scrum Master yana yin haka a kowane aiki.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Wakili","text":"AI da ke aiki shi kaɗai a kan aiki: yana karanta lamba, yana yin canje-canje, yana gudanar da bincike, yana ba da rahoto.","also":["agents","wakilai","agent"]},{"id":"token","g":"team","word":"Token","text":"Ma'aunin da ake ƙirga amfanin AI da shi: kusan ƴan haruffa na rubutu da aka karanta ko aka rubuta. Ƙarancin token, ƙarin tsarinku ya rage.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Ƙaramin umarni da ke gudana da kansa a lokaci da aka tsara, misali lokacin da zaman AI ya fara, don ƙungiya ta ji sharhinku.","also":["hooks"]}]}};
